    WHERE name = N'fk_queue_items_activity_id'
      AND parent_object_id = OBJECT_ID(N'[crm].[queue_items]')
)
BEGIN
    PRINT N'Creating foreign key constraint fk_queue_items_activity_id';
    ALTER TABLE [crm].[queue_items]
        ADD CONSTRAINT [fk_queue_items_activity_id]
        FOREIGN KEY ([activity_id])
        REFERENCES [crm].[activities]([id])
        ON DELETE NO ACTION ON UPDATE NO ACTION;
END
GO

