-- Junction table for ManyToMany: Contact <-> Opportunity
IF OBJECT_ID(N'[crm].[opportunity_contacts]', N'U') IS NULL
BEGIN
    PRINT N'CREATING junction table OpportunityContact';
    CREATE TABLE [crm].[opportunity_contacts]
    (
        [id] uniqueidentifier NOT NULL CONSTRAINT [df_opportunity_contacts_id] DEFAULT NEWID() CONSTRAINT [pk_opportunity_contacts] PRIMARY KEY,
        [contact_id] uniqueidentifier NOT NULL,
        [opportunity_id] uniqueidentifier NOT NULL,
        [created_at] datetimeoffset(7) NOT NULL CONSTRAINT [df_opportunity_contacts_created_at] DEFAULT SYSDATETIMEOFFSET(),
        CONSTRAINT [uq_opportunity_contacts] UNIQUE ([contact_id], [opportunity_id])
    );

    CREATE INDEX [idx_opportunity_contacts_contact_id]
        ON [crm].[opportunity_contacts] ([contact_id]);
    CREATE INDEX [idx_opportunity_contacts_opportunity_id]
        ON [crm].[opportunity_contacts] ([opportunity_id]);

    ALTER TABLE [crm].[opportunity_contacts]
        ADD CONSTRAINT [fk_opportunity_contacts_contact_id]
        FOREIGN KEY ([contact_id])
        REFERENCES [crm].[contacts]([id])
        ON DELETE CASCADE ON UPDATE CASCADE;

    ALTER TABLE [crm].[opportunity_contacts]
        ADD CONSTRAINT [fk_opportunity_contacts_opportunity_id]
        FOREIGN KEY ([opportunity_id])
        REFERENCES [crm].[opportunities]([id])
        ON DELETE NO ACTION ON UPDATE NO ACTION;
END
GO
